-- composition of rule kernels OrderBySubq x SimplifyJoin (sqlite), template cte_twice
WITH ka AS (SELECT a1.c0 AS c0, CAST(0.5 AS REAL) AS c1, a2.c0 AS c2, '1970-01-01' AS c3 FROM (tp AS a1 FULL JOIN t4 AS a2 ON (a1.c0 = a2.c1)) WHERE (a2.c0 > 100)), kb AS (WITH cte1 AS MATERIALIZED (SELECT CAST(5e-324 AS REAL) AS c0 ORDER BY 1) SELECT CAST(1 AS INTEGER) AS c0, CAST(1.5 AS NUMERIC) AS c1 FROM cte1 AS a1 GROUP BY a1.c0 UNION SELECT CAST(1 AS INTEGER) AS c0, CAST(42.5 AS NUMERIC) AS c1) SELECT (SELECT count(*) FROM ka) + (SELECT count(*) FROM kb) + (SELECT count(*) FROM ka);
-- pgfuzz:check kernel:cte_twice SELECT 2 * (SELECT count(*) FROM (SELECT a1.c0 AS c0, CAST(0.5 AS REAL) AS c1, a2.c0 AS c2, '1970-01-01' AS c3 FROM (tp AS a1 FULL JOIN t4 AS a2 ON (a1.c0 = a2.c1)) WHERE (a2.c0 > 100)) AS ka) + (SELECT count(*) FROM (WITH cte1 AS MATERIALIZED (SELECT CAST(5e-324 AS REAL) AS c0 ORDER BY 1) SELECT CAST(1 AS INTEGER) AS c0, CAST(1.5 AS NUMERIC) AS c1 FROM cte1 AS a1 GROUP BY a1.c0 UNION SELECT CAST(1 AS INTEGER) AS c0, CAST(42.5 AS NUMERIC) AS c1) AS kb)
